'use strict';

const fs = require('fs');
const [n, m, pInput] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const MOD = BigInt(pInput);

function modPow(base, exp) {
    let result = 1n;
    base %= MOD;
    while (exp > 0n) {
        if (exp & 1n) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1n;
    }
    return result;
}

const fact = Array(m + 1).fill(1n);
const invFact = Array(m + 1).fill(1n);
const inv = Array(m + 1).fill(0n);

for (let i = 1; i <= m; i++) {
    fact[i] = fact[i - 1] * BigInt(i) % MOD;
}

invFact[m] = modPow(fact[m], MOD - 2n);
for (let i = m; i >= 1; i--) {
    invFact[i - 1] = invFact[i] * BigInt(i) % MOD;
}
for (let i = 1; i <= m; i++) {
    inv[i] = fact[i - 1] * invFact[i] % MOD;
}

const count = Array(m + 1).fill(0n);
const madness = Array(m + 1).fill(0n);
count[0] = 1n;

for (let k = 1; k <= m; k++) {
    let countSum = 0n;
    let madnessSum = 0n;

    for (let left = 0; left < k; left++) {
        const right = k - 1 - left;

        let choose = fact[k - 1] * invFact[left] % MOD;
        choose = choose * invFact[right] % MOD;

        const pairCount = count[left] * count[right] % MOD;
        countSum += choose * pairCount;

        const previousMadness =
            (madness[left] * count[right] +
             count[left] * madness[right]) % MOD;

        const lastMadness =
            BigInt(
                left * (left + 1) / 2 +
                right * (right + 1) / 2
            );

        let term = BigInt(k + 1) * previousMadness;
        term += pairCount * lastMadness;
        madnessSum += choose * (term % MOD);
    }

    count[k] = BigInt(k + 1) * (countSum % MOD) % MOD;
    madness[k] = madnessSum % MOD;
}

const W = Array(m + 1).fill(0n);
const Q = Array(m + 1).fill(0n);
const A = Array(m + 1).fill(0n);

A[0] = 1n;
for (let k = 1; k <= m; k++) {
    W[k] = count[k] * invFact[k] % MOD;
    Q[k] = madness[k] * invFact[k] % MOD;
    A[k] = W[k];
}

const empty = n - m;
const power = Array(m + 1).fill(0n);
power[0] = 1n;

// power(x) = A(x)^(n-m), truncated to degree m.
for (let k = 1; k <= m; k++) {
    let sum = 0n;

    for (let i = 1; i <= k; i++) {
        const coefficient = (empty + 1) * i - k;
        if (coefficient === 0) continue;

        const product = A[i] * power[k - i] % MOD;
        sum += product * BigInt(coefficient);
    }

    sum %= MOD;
    if (sum < 0n) sum += MOD;
    power[k] = sum * inv[k] % MOD;
}

let normalizedAnswer = 0n;
for (let k = 1; k <= m; k++) {
    normalizedAnswer += Q[k] * power[m - k];
}
normalizedAnswer %= MOD;

let answer = normalizedAnswer * BigInt(empty + 1) % MOD;
answer = answer * fact[m] % MOD;

console.log(answer.toString());

const fs = require('fs');

const [n, m, p] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const BASE = 32768;

function mulMod(a, b) {
    const high = Math.floor(b / BASE);
    const low = b - high * BASE;
    return (((a * high) % p) * BASE + a * low) % p;
}

const inv = new Array(m + 1).fill(0);
if (m >= 1) inv[1] = 1;

for (let i = 2; i <= m; i++) {
    const q = Math.floor(p / i);
    inv[i] = (p - mulMod(q, inv[p % i])) % p;
}

const H = new Array(m + 1).fill(0);
const Q = new Array(m + 1).fill(0);
H[0] = 1;

for (let k = 1; k <= m; k++) {
    let sumH = 0;
    let sumQ = 0;

    for (let x = 0; x < k; x++) {
        const y = k - 1 - x;
        const productH = mulMod(H[x], H[y]);

        sumH += productH;

        const previousCost =
            (mulMod(Q[x], H[y]) + mulMod(H[x], Q[y])) % p;

        const triangular =
            x * (x + 1) / 2 + y * (y + 1) / 2;

        let term = mulMod(k + 1, previousCost);
        term += mulMod(triangular % p, productH);
        sumQ += term % p;
    }

    H[k] = mulMod(
        mulMod(sumH % p, (k + 1) % p),
        inv[k]
    );

    Q[k] = mulMod(sumQ % p, inv[k]);
}

const componentsSlots = n - m + 1;
const exponent = componentsSlots - 1;
const P = new Array(m + 1).fill(0);
P[0] = 1;

for (let k = 1; k <= m; k++) {
    let sum = 0;

    for (let i = 1; i <= k; i++) {
        const coefficient = (exponent + 1) * i - k;
        if (coefficient === 0) continue;

        const product = mulMod(H[i], P[k - i]);
        const coefficientMod =
            ((coefficient % p) + p) % p;

        sum += mulMod(product, coefficientMod);
    }

    P[k] = mulMod(sum % p, inv[k]);
}

let totalCost = 0;
for (let k = 1; k <= m; k++) {
    totalCost += mulMod(Q[k], P[m - k]);
}

let factorial = 1;
for (let i = 2; i <= m; i++) {
    factorial = mulMod(factorial, i);
}

let answer = mulMod(totalCost % p, componentsSlots % p);
answer = mulMod(answer, factorial);

console.log(answer);

