for (let k = 1; k <= m; k++) {
    const trees = modPow(BigInt(k + 1), BigInt(k - 1));
    c[k] = pow2[k] * trees % MOD * invFact[k] % MOD;
}

for (let k = 1; k <= m; k++) {
    let convolution = 0n;
    let distance = 0n;

    for (let l = 0; l < k; l++) {
        const r = k - 1 - l;
