'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [n, m, MOD] = input;

const BASE = 32768;

function mul(a, b) {
    const high = Math.floor(b / BASE);
    const low = b - high * BASE;
    return ((a * low) % MOD + ((a * high) % MOD) * BASE) % MOD;
}

function add(a, b) {
    const result = a + b;
    return result >= MOD ? result - MOD : result;
}

const inverse = new Array(m + 1).fill(0);
if (m >= 1) inverse[1] = 1;

for (let i = 2; i <= m; i++) {
    inverse[i] = MOD - mul(Math.floor(MOD / i), inverse[MOD % i]);
    if (inverse[i] === MOD) inverse[i] = 0;
}

const w = new Array(m + 1).fill(0);
const h = new Array(m + 1).fill(0);
w[0] = 1;

for (let size = 1; size <= m; size++) {
    let sumW = 0;
    let sumH = 0;

    for (let left = 0; left < size; left++) {
        const right = size - 1 - left;

        const productW = mul(w[left], w[right]);
        sumW = add(sumW, productW);

        const crossCost = add(
            mul(h[left], w[right]),
            mul(w[left], h[right])
        );

        const lastMadness =
            left * (left + 1) / 2 +
            right * (right + 1) / 2;

        const term = add(
            mul(crossCost, size + 1),
            mul(productW, lastMadness)
        );

        sumH = add(sumH, term);
    }

    w[size] = mul(mul(sumW, size + 1), inverse[size]);
    h[size] = mul(sumH, inverse[size]);
}

const exponent = n - m;
const power = new Array(m + 1).fill(0);
power[0] = 1;

if (exponent > 0) {
    for (let degree = 1; degree <= m; degree++) {
        let sum = 0;

        for (let i = 1; i <= degree; i++) {
            let factor = (exponent + 1) * i - degree;
            factor %= MOD;
            if (factor < 0) factor += MOD;

            const term = mul(mul(w[i], power[degree - i]), factor);
            sum = add(sum, term);
        }

        power[degree] = mul(sum, inverse[degree]);
    }
}

let coefficient = 0;
for (let size = 1; size <= m; size++) {
    coefficient = add(
        coefficient,
        mul(h[size], power[m - size])
    );
}

let factorial = 1;
for (let i = 2; i <= m; i++) {
    factorial = mul(factorial, i);
}

const componentSlots = n - m + 1;
const answer = mul(mul(coefficient, componentSlots), factorial);

console.log(answer.toString());

'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [n, m, p] = input;

const BASE = 32768;

function mulMod(a, b) {
    const high = Math.floor(b / BASE);
    const low = b - high * BASE;
    return (((a * high) % p) * BASE + a * low) % p;
}

const inv = new Array(m + 1).fill(0);
inv[1] = 1;

for (let i = 2; i <= m; i++) {
    const q = Math.floor(p / i);
    const r = p % i;
    const value = mulMod(q, inv[r]);
    inv[i] = value === 0 ? 0 : p - value;
}

const f = new Array(m + 1).fill(0);
const g = new Array(m + 1).fill(0);
f[0] = 1;

for (let k = 1; k <= m; k++) {
    let sumF = 0;
    let sumG = 0;
    let sumMadness = 0;

    for (let x = 0; x < k; x++) {
        const y = k - 1 - x;
        const ff = mulMod(f[x], f[y]);

        sumF += ff;
        if (sumF >= p) sumF -= p;

        let inherited = mulMod(g[x], f[y]) + mulMod(f[x], g[y]);
        if (inherited >= p) inherited -= p;

        sumG += inherited;
        if (sumG >= p) sumG -= p;

        const triangleX = x * (x + 1) / 2;
        const triangleY = y * (y + 1) / 2;
        const local = (ff * (triangleX + triangleY)) % p;

        sumMadness += local;
        if (sumMadness >= p) sumMadness -= p;
    }

    const weightedF = (sumF * (k + 1)) % p;
    f[k] = mulMod(weightedF, inv[k]);

    let weightedG = (sumG * (k + 1)) % p;
    weightedG += sumMadness;
    if (weightedG >= p) weightedG -= p;
    g[k] = mulMod(weightedG, inv[k]);
}

const empty = n - m;
const h = new Array(m + 1).fill(0);
h[0] = 1;

// h(x) = (1 + f[1]x + f[2]x^2 + ...)^empty
for (let k = 1; k <= m; k++) {
    let sum = 0;

    for (let i = 1; i <= k; i++) {
        const coefficient = (empty + 1) * i - k;
        if (coefficient === 0) continue;

        const product = mulMod(f[i], h[k - i]);
        const term = (product * Math.abs(coefficient)) % p;

        if (coefficient > 0) {
            sum += term;
            if (sum >= p) sum -= p;
        } else {
            sum -= term;
            if (sum < 0) sum += p;
        }
    }

    h[k] = mulMod(sum, inv[k]);
}

let coefficient = 0;
for (let k = 1; k <= m; k++) {
    coefficient += mulMod(g[k], h[m - k]);
    if (coefficient >= p) coefficient -= p;
}

let factorial = 1;
for (let i = 2; i <= m; i++) {
    factorial = (factorial * i) % p;
}

coefficient = (coefficient * (empty + 1)) % p;
const answer = mulMod(coefficient, factorial);

console.log(answer);
